#include<cstdio>
#include<cstring>
#include<algorithm>
#define LL long long
using namespace std;

const int N=5e5+5,X=1e9;
const LL INF=1e18;
int n,d,p;
int a[N],b[N];

LL f[N];
int q[N],head,tail;
bool check(int flex)
{
	for(int i=head;i<=tail;i++)
		q[i]=0;
	head=1,tail=0;  
	fill(f+1,f+n+1,-INF);  
	LL pts=f[0]=0;
	int pos=0;  
	for(int i=1;i<=n;i++)
	{

		while(a[i]-a[pos]>=max(d-flex,1))  
		{
			while(head<=tail && f[q[tail]]<=f[pos])
				q[tail--]=0;
			q[++tail]=pos;


			pos++;
		}
		while(head<=tail && a[q[head]]+d+flex<a[i])  
			q[head++]=0;
		if(head<=tail) f[i]=b[i]+f[q[head]];
		pts=max(pts,f[i]);
	}
	return pts>=p;
}

int main()
{
	scanf("%d%d%d",&n,&d,&p);
	for(int i=1;i<=n;i++)
		scanf("%d%d",&a[i],&b[i]);
	int l=-1,r=X+1;
	while(l+1<r)
	{
		int mid=l+r>>1;
		if(check(mid)) r=mid;
		else l=mid;
	}
	printf("%d\n",r>X?-1:r);
	return 0;
}
